@inject Services.WarehouseState WarehouseState
@inject Services.InventoryAlertState AlertState
@implements IDisposable
@rendermode InteractiveServer

<select class="form-select form-select-sm" value="@WarehouseState.SelectedWarehouseId"
        @onchange="OnWarehouseChanged" style="max-width: 200px;">
    @foreach (var (id, name) in Services.WarehouseState.AvailableWarehouses)
    {
        <option value="@id">@name</option>
    }
</select>

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        WarehouseState.OnChange += _handler;
    }

    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        var warehouseId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(warehouseId))
        {
            WarehouseState.SetWarehouse(warehouseId);
            // Refresh alert data for the newly selected warehouse
            await AlertState.RefreshAsync();
        }
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= _handler;
    }
}

@inject Services.InventoryAlertState AlertState
@implements IDisposable
@rendermode InteractiveServer

<span class="badge bg-danger rounded-pill">@AlertState.LowStockCount</span>

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        AlertState.OnChange += _handler;
    }

    public void Dispose()
    {
        AlertState.OnChange -= _handler;
    }
}

