@page "/dashboard"
@inject Services.WarehouseState WarehouseState
@inject Services.InventoryAlertState AlertState
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard - @WarehouseState.SelectedWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>
<p class="text-muted">Currently viewing: <strong>@WarehouseState.SelectedWarehouseName</strong></p>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="display-4 text-danger">@AlertState.LowStockCount</p>
                <p class="text-muted">Items below minimum levels</p>
                <small class="text-secondary">Auto-refreshes every 10 seconds</small>
            </div>
        </div>
    </div>
</div>

@code {
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override async Task OnInitializedAsync()
    {
        _warehouseHandler = () => InvokeAsync(StateHasChanged);
        _alertHandler = () => InvokeAsync(StateHasChanged);

        WarehouseState.OnChange += _warehouseHandler;
        AlertState.OnChange += _alertHandler;

        // Start polling when the dashboard becomes visible
        await AlertState.StartPollingAsync();
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= _warehouseHandler;
        AlertState.OnChange -= _alertHandler;

        // Stop polling when the user leaves the dashboard
        AlertState.StopPolling();
    }
}

